package com.tradingplatform.paper;
import java.math.BigDecimal; import java.time.Instant; import java.util.UUID;
public final class PaperDtos { private PaperDtos(){} public record OrderRequest(String symbol,PaperSide side,int quantity,BigDecimal stopLoss,BigDecimal target){} public record Account(UUID id,BigDecimal initialBalance,BigDecimal availableCash,BigDecimal usedMargin,BigDecimal realizedPnl,BigDecimal unrealizedPnl,BigDecimal totalPnl,BigDecimal dailyPnl){} public record Position(UUID id,String symbol,String exchange,PaperSide side,int quantity,BigDecimal averageEntryPrice,BigDecimal currentPrice,BigDecimal unrealizedPnl,BigDecimal realizedPnl,BigDecimal stopLoss,BigDecimal target,PaperPositionStatus status,Instant openedAt){} public record Order(UUID id,String symbol,PaperSide side,int quantity,BigDecimal requestedPrice,BigDecimal executionPrice,PaperOrderStatus status,BigDecimal charges,String rejectionReason,Instant timestamp){} }
